<script setup lang="ts">
import { ref,computed,onMounted } from 'vue'
import { ElMessage } from 'element-plus'
import type { Api } from './api'
import PageHeader from './PageHeader.vue'
const props=defineProps<{api:Api;catalog:Record<string,{id:string;name?:string}[]>}>()
interface Grant {action:string;scope:string;scope_id:string|null}
interface Role {id:string;name:string;version:number;grants:Grant[];enabled_menus:string[]|null}
const menus=ref<{key:string;label:string}[]>([])
const activeId=ref('')
const activeRoles=computed(()=>roles.value.filter(r=>r.id===activeId.value))
const roles=ref<Role[]>([]), name=ref(''), busy=ref(false)
const actions:Record<string,string>={'talent.read':'人才查看','talent.write':'人才编辑','file.read':'文件查看','file.write':'文件上传','task.run':'解析执行','requirement.read':'需求查看','requirement.write':'需求维护','account.manage':'账号角色管理','catalog.manage':'基础资料维护','audit.read':'审计查看','assessment.manage':'题库试卷管理','assessment.assign':'测评分配','assessment.read':'测评结果查看','chat.use':'档案聊天'}
const scopes:Record<string,string>={self:'本人',department:'指定部门',internal_all:'全公司内部',external_all:'全部外部',owner:'本人负责外部',pool:'指定人才库',global:'全局管理'}
async function run(fn:()=>Promise<void>){busy.value=true;try{await fn()}catch(e){ElMessage.error((e as Error).message)}finally{busy.value=false}}
async function load(){menus.value=await props.api('/admin/menu-options');roles.value=await props.api('/admin/roles');for(const r of roles.value)r.enabled_menus??=menus.value.map(m=>m.key);if(!roles.value.some(r=>r.id===activeId.value))activeId.value=roles.value[0]?.id||''}
async function saveMenus(r:Role){await run(async()=>{await props.api(`/admin/roles/${r.id}/menus`,'PUT',{version:r.version,menus:r.enabled_menus});await load();ElMessage.success('菜单显示配置已保存；API仍按功能与数据范围授权')})}
async function create(){await run(async()=>{const created=await props.api<Role>('/admin/roles','POST',{name:name.value});activeId.value=created.id;name.value='';await load()})}
async function save(r:Role){await run(async()=>{await props.api(`/admin/roles/${r.id}/grants`,'PUT',{version:r.version,grants:r.grants.map(g=>({action:g.action,scope:g.scope,scope_id:['department','pool'].includes(g.scope)?g.scope_id:null}))});await load();ElMessage.success('角色权限已保存，下次请求即生效')})}
function options(action:string){return ['account.manage','catalog.manage','audit.read','assessment.manage'].includes(action)?['global']:action.startsWith('requirement.')?['global','department']:['self','department','internal_all','external_all','owner','pool']}
onMounted(()=>run(load))
</script>
<template><PageHeader title="角色与菜单权限" subtitle="每项动作独立配置；菜单显示与功能权限取交集，管理员不自动拥有业务资料权限"/><div class="role-layout"><section class="role-list"><h2>角色</h2><button v-for="r in roles" :key="r.id" :class="{active:activeId===r.id}" @click="activeId=r.id"><span class="role-name">{{r.name}}</span><span class="role-meta">{{r.grants.length}} 项授权</span></button><label for="new-role-name">新角色名称</label><el-input id="new-role-name" v-model="name"/><el-button :loading="busy" @click="create">创建角色</el-button></section><section class="role-editor"><el-card v-for="r in activeRoles" :key="r.id"><div class="role-editor-head"><h2>{{r.name}} · v{{r.version}}</h2><span class="muted">{{r.grants.length}} 项授权 · 显示 {{r.enabled_menus?.length??0}} 个菜单</span></div><div class="grant-labels"><span>功能动作</span><span>数据范围</span></div><p v-if="!r.grants.length" class="muted grant-empty">尚未配置功能授权；没有任何授权时，该角色看不到业务菜单，也不能访问业务接口。</p><div v-for="(g,i) in r.grants" :key="i" class="file-row grant-row"><el-select aria-label="功能动作" v-model="g.action" @change="g.scope=options(g.action)[0];g.scope_id=null"><el-option v-for="(label,value) in actions" :key="value" :label="label" :value="value"/></el-select><el-select aria-label="数据范围" v-model="g.scope" @change="g.scope_id=null"><el-option v-for="s in options(g.action)" :key="s" :value="s" :label="scopes[s]"/></el-select><el-select v-if="['department','pool'].includes(g.scope)" v-model="g.scope_id" placeholder="指定范围"><el-option v-for="c in catalog[g.scope==='department'?'departments':'pools']" :key="c.id" :value="c.id" :label="c.name"/></el-select><el-button @click="r.grants.splice(i,1)">移除</el-button></div><h3>菜单显示范围</h3><p class="muted">显示菜单还需具备对应功能权限；隐藏菜单不撤销功能授权，撤权请修改上方授权。</p><el-checkbox-group v-model="r.enabled_menus"><el-checkbox v-for="m in menus" :key="m.key" :value="m.key">{{m.label}}</el-checkbox></el-checkbox-group><el-button @click="saveMenus(r)">保存菜单配置</el-button><el-divider/><el-button @click="r.grants.push({action:'talent.read',scope:'self',scope_id:null})">增加授权</el-button><el-button type="primary" :loading="busy" @click="save(r)">保存全部授权</el-button></el-card></section></div></template>

<style scoped>
.role-layout{display:grid;grid-template-columns:230px minmax(0,1fr);gap:16px;align-items:start}.role-list{padding:16px;background:var(--surface);border:1px solid var(--border);border-radius:var(--radius)}.role-list h2{font-size:14px;margin:0 0 6px}.role-list>button:not(.el-button){display:flex;align-items:center;justify-content:space-between;gap:10px;text-align:left;cursor:pointer;border:1px solid transparent;background:transparent;color:var(--text);width:100%;padding:10px 12px;border-radius:8px;margin:4px 0;transition:border-color .15s,background .15s}.role-list>button:not(.el-button):hover{border-color:var(--accent)}.role-list>button.active{background:var(--accent-soft);border-color:var(--accent)}.role-name{font-size:13px;font-weight:550;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.role-list>button.active .role-name{color:var(--accent)}.role-meta{flex-shrink:0;font-size:11px;color:var(--text-tertiary);background:var(--surface-muted);border-radius:10px;padding:2px 8px}.role-list>button.active .role-meta{background:var(--surface);color:var(--accent)}.role-list label{display:block;font-size:12px;margin:18px 0 8px}.role-list .el-button{margin:10px 0 0;width:100%}.role-editor-head{display:flex;align-items:baseline;justify-content:space-between;gap:12px;flex-wrap:wrap;margin-bottom:12px}.role-editor-head h2{margin:0;font-size:16px}.grant-labels{display:grid;grid-template-columns:1fr 1fr;gap:12px;font-size:12px;color:var(--text-secondary)}.grant-row{display:flex;gap:8px;flex-wrap:wrap;align-items:center;padding:8px 10px;border:1px solid var(--border);border-radius:8px;margin-bottom:8px}.grant-empty{margin:10px 0 0;font-size:12px;line-height:1.7}.grant-row .el-select{width:210px;max-width:100%}.role-editor{min-width:0}.role-editor>.el-card{margin:0}.role-editor .el-checkbox-group{display:flex;flex-wrap:wrap}.role-editor .el-checkbox{margin-right:18px}@media(max-width:1000px){.role-layout{grid-template-columns:1fr}.role-list{display:flex;gap:8px;flex-wrap:wrap;align-items:center}.role-list h2{width:100%}.role-list>button:not(.el-button){width:auto}.role-list label{margin:0}.role-list .el-input{width:180px}.role-list .el-button{width:auto;margin:0}.grant-labels{display:none}}
</style>
